additional=[]
for ui, unit in enumerate(data['units']):
    definitions=clues[ui].split(';')
    assert len(definitions)==40, (ui,len(definitions))
    rng=random.Random(20261010+ui)
    for wi,(word,clue) in enumerate(zip(unit['words'],definitions)):
        excluded={word['t']}
        for group in aliases:
            if word['t'] in group: excluded |= group
        candidates=[w for w in unit['words'] if w['t'] not in excluded]
        rng.shuffle(candidates)
        options=[word['t']]+[w['t'] for w in candidates[:3]]
        additional.append(dict(id=f'en-a1-u{ui}-clue-{wi}',unitIndex=ui,type='choice',prompt='Which word or phrase has this meaning?',passage=clue,choices=options,answer=0,objective='vocabulary-in-context',explanation=f"{word['t']} : {word['fr']}. Indice : {clue}"))
    # Forty different four-pair rounds, with no duplicated translation and
    # balanced exposure: each lexical entry occurs exactly four times.
    used={tuple(sorted(w['id'] for w in unit['words'][:4]))}
    exposure={w['id']:0 for w in unit['words']}
    for mi in range(40):
        for attempt in range(10000):
            candidates=list(unit['words']);rng.shuffle(candidates)
            candidates.sort(key=lambda w:exposure[w['id']])
            pairs=candidates[:4]
            key=tuple(sorted(w['id'] for w in pairs))
            if key not in used and len({w['fr'].lower() for w in pairs})==4: break
        else: raise ValueError('Cannot build matching set')
        used.add(key)
        for w in pairs: exposure[w['id']]+=1
        additional.append(dict(id=f'en-a1-u{ui}-pairs-{mi}',unitIndex=ui,type='match',pairIds=[w['id'] for w in pairs],objective='vocabulary-review'))
    assert set(exposure.values())=={4}, (ui,exposure)

