for ui,rows in enumerate(readings):
    for ri,row in enumerate(rows.splitlines()):
        passage,*fields=row.split('|')
        assert len(fields)==10
        for qi in range(2):
            prompt,*options=fields[qi*5:qi*5+5]
            additional.append(dict(id=f'en-a1-u{ui}-extra-reading-{ri}-{qi}',unitIndex=ui,type='choice',passage=passage,prompt=prompt,choices=options,answer=0,objective='reading-comprehension',explanation=f"Réponse : {options[0]}. Le texte précise : {passage}"))
assert len(additional)==1080
(root/'content/en/A1-expanded.json').write_text(json.dumps(additional,ensure_ascii=False,indent=2)+'\n')
print(f'{len(additional)} contextual clues and matching games authored')
